# shellcheck shell=bash
# iSH-AOK image optimizer; loaded after ios-linuxkit.

systui_aok_dir(){ printf '%s\n' "${SYSTUI_STATE_DIR:-/etc/systui}/ish-aok"; }
systui_aok_file(){ printf '%s/%s.conf\n' "$(systui_aok_dir)" "$1"; }
systui_aok_get(){ local f v; f=$(systui_aok_file "$1"); v=$([ -r "$f" ] && sed -n "s/^$2=//p" "$f" | tail -1); printf '%s\n' "${v:-$3}"; }
systui_aok_set(){ local i="$1" k="$2" v="$3" f t l; case "$k" in ARCH|PRESET|HLE|CRYPTO|PIXMAN|HLE_STATS|JIT_FUSION|RETCACHE|NATIVE|SHELL|FUSE|BINFMT|SWAP|SWAP_SIZE|TMPFS|FILE_PROVIDER|LOG) ;; *) return 2;; esac; mkdir -p "$(systui_aok_dir)" || return 1; f=$(systui_aok_file "$i"); t="$f.$$"; [ -r "$f" ] && while IFS= read -r l || [ -n "$l" ]; do case "$l" in "$k="*) continue;; esac; printf '%s\n' "$l" >>"$t"; done <"$f"; printf '%s=%s\n' "$k" "$v" >>"$t"; mv "$t" "$f"; }
systui_aok_arch(){ local r="$IOSKIT_IMAGES_DIR/$1" x; x=$(systui_aok_get "$1" ARCH ''); [ -n "$x" ] && { printf '%s\n' "$x"; return; }; x=$(file "$r/bin/sh" 2>/dev/null || true); case "$x" in *aarch64*|*ARM64*) echo arm64;; *RISC-V*) echo riscv64;; *x86-64*) echo amd64;; *80386*) echo i386;; *) echo unknown;; esac; }
systui_aok_toggle(){ [ "$3" = on ] && systui_aok_set "$1" "$2" off || systui_aok_set "$1" "$2" on; }

systui_aok_preset(){ local i="$1" p="$2" a; a=$(systui_aok_arch "$i"); systui_aok_set "$i" ARCH "$a"; systui_aok_set "$i" PRESET "$p"; case "$p" in max) [ "$a" = arm64 ] || [ "$a" = riscv64 ] && systui_aok_set "$i" HLE on; systui_aok_set "$i" CRYPTO on; systui_aok_set "$i" PIXMAN on; systui_aok_set "$i" JIT_FUSION all; systui_aok_set "$i" RETCACHE on; systui_aok_set "$i" NATIVE on; systui_aok_set "$i" SHELL zsh; systui_aok_set "$i" SWAP conservative; systui_aok_set "$i" TMPFS aggressive; systui_aok_set "$i" LOG off;; memory) systui_aok_set "$i" HLE auto; systui_aok_set "$i" CRYPTO on; systui_aok_set "$i" PIXMAN off; systui_aok_set "$i" JIT_FUSION all; systui_aok_set "$i" RETCACHE on; systui_aok_set "$i" SWAP conservative; systui_aok_set "$i" SWAP_SIZE 1G; systui_aok_set "$i" TMPFS minimal; systui_aok_set "$i" LOG off;; battery) systui_aok_set "$i" HLE auto; systui_aok_set "$i" CRYPTO on; systui_aok_set "$i" PIXMAN off; systui_aok_set "$i" JIT_FUSION all; systui_aok_set "$i" RETCACHE on; systui_aok_set "$i" SWAP off; systui_aok_set "$i" TMPFS auto; systui_aok_set "$i" LOG off;; *) systui_aok_set "$i" HLE auto; systui_aok_set "$i" CRYPTO auto; systui_aok_set "$i" PIXMAN off; systui_aok_set "$i" JIT_FUSION all; systui_aok_set "$i" RETCACHE on; systui_aok_set "$i" NATIVE on; systui_aok_set "$i" SHELL zsh; systui_aok_set "$i" SWAP conservative; systui_aok_set "$i" SWAP_SIZE 512M; systui_aok_set "$i" TMPFS auto; systui_aok_set "$i" LOG minimal;; esac; }

systui_aok_status(){ local i="$1"; printf 'iSH-AOK image optimization\n==========================\n\nImage: %s\nABI: %s\nPreset: %s\n\n' "$i" "$(systui_aok_arch "$i")" "$(systui_aok_get "$i" PRESET balanced)"; for k in HLE CRYPTO PIXMAN HLE_STATS JIT_FUSION RETCACHE NATIVE SHELL FUSE BINFMT SWAP SWAP_SIZE TMPFS FILE_PROVIDER LOG; do printf '%-16s %s\n' "$k" "$(systui_aok_get "$i" "$k" auto)"; done; }
systui_aok_apply(){ local i="$1" r="$IOSKIT_IMAGES_DIR/$1" a h c p; [ -d "$r" ] || return 1; mkdir -p "$r/etc/systui" || return 1; a=$(systui_aok_arch "$i"); h=$(systui_aok_get "$i" HLE auto); c=$(systui_aok_get "$i" CRYPTO auto); p=$(systui_aok_get "$i" PIXMAN off); { echo '# generated by SystUI'; echo "SYSTUI_AOK_GUEST_ARCH=$a"; echo "SYSTUI_AOK_JIT_FUSION=$(systui_aok_get "$i" JIT_FUSION all)"; echo "SYSTUI_AOK_RET_CACHE=$(systui_aok_get "$i" RETCACHE on)"; [ "$h" = on ] || { [ "$h" = auto ] && { [ "$a" = arm64 ] || [ "$a" = riscv64 ]; }; }; [ $? = 0 ] && echo ISH_HLE=1 || echo ISH_HLE=0; [ "$c" = off ] && echo ISH_CRYPTO_ACCEL=0 || echo ISH_CRYPTO_ACCEL=1; [ "$p" = on ] && echo ISH_PIX_ACCEL=1 || echo ISH_PIX_ACCEL=0; [ "$(systui_aok_get "$i" HLE_STATS off)" = on ] && echo ISH_HLE_STATS=1 || echo ISH_HLE_STATS=0; } >"$r/etc/systui/ish-aok.env"; cat >"$r/etc/systui/ish-aok-tune.sh" <<'EOS'
#!/bin/sh
a="${SYSTUI_AOK_GUEST_ARCH:-$(uname -m)}"; [ "$a" = aarch64 ] && a=arm64; [ "$a" = x86_64 ] && a=amd64
n="/proc/ish/${a}_jit_fuse"; [ -w "$n" ] || exit 0
[ "${SYSTUI_AOK_JIT_FUSION:-all}" = all ] && echo all=1 >"$n" || echo all=0 >"$n"
[ "${SYSTUI_AOK_RET_CACHE:-on}" = on ] && echo retcache=1 >"$n" || echo retcache=0 >"$n"
EOS
chmod +x "$r/etc/systui/ish-aok-tune.sh"; tui_msg 'iSH-AOK' "Applied image-local runtime profile to:\n$r/etc/systui\n\nSwap and File Provider remain app-level desired policies."; }

systui_aok_accel(){ local i="$1" c v; while true; do tui_capture_menu c tui_menu_no_tags 'Accelerators' "ABI: $(systui_aok_arch "$i")" hle "HLE: $(systui_aok_get "$i" HLE auto)" crypto "Crypto: $(systui_aok_get "$i" CRYPTO auto)" pix "Pixman: $(systui_aok_get "$i" PIXMAN off)" stats "HLE stats: $(systui_aok_get "$i" HLE_STATS off)" back Back || return $?; case "$c" in hle|crypto) v=$(tui_menu Policy 'Select' auto Automatic on On off Off) || continue; [ -n "$v" ] && systui_aok_set "$i" "$(printf '%s' "$c"|tr a-z A-Z)" "$v";; pix) systui_aok_toggle "$i" PIXMAN "$(systui_aok_get "$i" PIXMAN off)";; stats) systui_aok_toggle "$i" HLE_STATS "$(systui_aok_get "$i" HLE_STATS off)";; back|'') return;; esac; done; }
systui_aok_jit(){ local i="$1" c v; while true; do tui_capture_menu c tui_menu_no_tags 'JIT tuning' 'Changes affect newly translated blocks.' fusion "Fusion: $(systui_aok_get "$i" JIT_FUSION all)" ret "Return cache: $(systui_aok_get "$i" RETCACHE on)" ab 'A/B benchmark instructions' back Back || return $?; case "$c" in fusion) v=$(tui_menu Fusion Select all 'All families' off Disabled) || continue; systui_aok_set "$i" JIT_FUSION "$v";; ret) systui_aok_toggle "$i" RETCACHE "$(systui_aok_get "$i" RETCACHE on)";; ab) tui_msg 'JIT A/B' 'Inside iSH-AOK run: sh /AOK/tests/jit_fuse_ab.sh\n\nUse fresh processes for measurements.';; back|'') return;; esac; done; }
systui_aok_advanced(){ local i="$1" c v; while true; do tui_capture_menu c tui_menu_no_tags 'Advanced iSH-AOK features' 'Fork-specific image and app policies.' native "Native tools: $(systui_aok_get "$i" NATIVE on)" shell "Native shell: $(systui_aok_get "$i" SHELL zsh)" fuse "FUSE: $(systui_aok_get "$i" FUSE on)" binfmt "binfmt_misc: $(systui_aok_get "$i" BINFMT on)" tmpfs "tmpfs: $(systui_aok_get "$i" TMPFS auto)" fp "File Provider: $(systui_aok_get "$i" FILE_PROVIDER auto)" log "Logging: $(systui_aok_get "$i" LOG minimal)" back Back || return $?; case "$c" in native|fuse|binfmt) k=$(printf '%s' "$c"|tr a-z A-Z); systui_aok_toggle "$i" "$k" "$(systui_aok_get "$i" "$k" on)";; shell) v=$(tui_menu Shell Select zsh 'Native zsh' bash 'Native bash if built' guest 'Guest shell') || continue; systui_aok_set "$i" SHELL "$v";; tmpfs) v=$(tui_menu tmpfs Select auto Automatic aggressive 'Performance/build cache' minimal 'Conserve memory') || continue; systui_aok_set "$i" TMPFS "$v";; fp) v=$(tui_menu 'File Provider' Select auto Automatic on Enabled off Disabled) || continue; systui_aok_set "$i" FILE_PROVIDER "$v";; log) v=$(tui_menu Logging Select off Off minimal Minimal strace Strace verbose Verbose) || continue; systui_aok_set "$i" LOG "$v";; back|'') return;; esac; done; }
systui_aok_memory(){ local i="$1" c v; while true; do tui_capture_menu c tui_menu_no_tags 'Memory and simulated swap' 'Swap is flash-backed and applied by the iSH-AOK app on next start.' mode "Policy: $(systui_aok_get "$i" SWAP conservative)" size "Target: $(systui_aok_get "$i" SWAP_SIZE 512M)" info 'Wear/thrash notes' back Back || return $?; case "$c" in mode) v=$(tui_menu Swap Select off Disabled conservative 'Memory-heavy only' always 'Prefer enabled') || continue; systui_aok_set "$i" SWAP "$v";; size) v=$(tui_input 'Swap target' 'e.g. 256M, 512M, 1G' "$(systui_aok_get "$i" SWAP_SIZE 512M)") || continue; [ -n "$v" ] && systui_aok_set "$i" SWAP_SIZE "$v";; info) tui_msg Swap 'iSH-AOK swap is opt-in, flash-backed, write-budgeted, thrash-guarded and suspension-aware. SystUI records the desired policy; the app owns the actual switch.';; back|'') return;; esac; done; }
systui_aok_presets(){ local i="$1" p; p=$(tui_menu 'Performance preset' "$i" balanced Balanced max 'Maximum performance' memory 'Memory-heavy' battery Efficiency custom 'Keep custom') || return; [ "$p" = custom ] || systui_aok_preset "$i" "$p"; }
systui_aok_image_menu(){ local i="$1" c; while true; do tui_capture_menu c tui_menu_no_tags "iSH-AOK — $i" "$(systui_aok_arch "$i") / $(systui_aok_get "$i" PRESET balanced)" status 'Status' preset 'Performance presets' accel 'Accelerators' jit 'JIT tuning' memory 'Memory and simulated swap' advanced 'Advanced fork features' apply 'Apply image-local profile' back Back || return $?; case "$c" in status) systui_ioskit_show_text 'iSH-AOK status' systui_aok_status "$i";; preset) systui_aok_presets "$i";; accel) systui_aok_accel "$i";; jit) systui_aok_jit "$i";; memory) systui_aok_memory "$i";; advanced) systui_aok_advanced "$i";; apply) systui_aok_apply "$i";; back|'') return;; esac; done; }
systui_aok_menu(){ local c i; while true; do tui_capture_menu c tui_menu_no_tags 'iSH-AOK configuration' 'Per-image performance and advanced fork controls.' select 'Select image' default "Default image (${IOSKIT_DEFAULT_IMAGE:-none})" about 'Optimization coverage' back Back || return $?; case "$c" in select) i=$(systui_ioskit_choose_image) || continue; [ -n "$i" ] && systui_aok_image_menu "$i";; default) [ -n "$IOSKIT_DEFAULT_IMAGE" ] && systui_aok_image_menu "$IOSKIT_DEFAULT_IMAGE" || tui_msg iSH-AOK 'No default image.';; about) tui_msg iSH-AOK 'Tunes JIT fusion/retcache, HLE, crypto, Pixman, native tools/shell, FUSE, binfmt_misc, tmpfs policy, simulated-swap intent, File Provider policy and logging.';; back|'') return;; esac; done; }

systui_ioskit_guestfs_menu(){ local c; while true; do tui_capture_menu c tui_menu_no_tags 'Guest root filesystems' "Images: $(systui_ioskit_image_count) default: ${IOSKIT_DEFAULT_IMAGE:-none}" manage 'Manage images' aok 'iSH-AOK optimization and advanced features' run 'Run guest' host 'Host integration' back Back || return $?; case "$c" in manage) systui_ioskit_images_menu;; aok) systui_aok_menu;; run) systui_ioskit_run_menu;; host) systui_ioskit_host_menu;; back|'') return;; esac; done; }
return 0 2>/dev/null || true